def solve(name, team):
    class Person:
        def __init__(self, name):
            cleaned = name.strip()
            if not cleaned:
                raise ValueError("blank")
            self.name = cleaned

    class Member(Person):
        def __init__(self, name, team):
            super().__init__(name)
            self.team = team

    try:
        member = Member(name, team)
    except ValueError:
        return "error"
    return member.name + ":" + member.team
